import{_ as a,a as e,b as i,c as r,d as s,e as o,f as n}from"./chunks/remove-4.D6zShIqt.js";import{_ as l,o as g,c as d,a5 as c}from"./chunks/framework.DGp912Ge.js";const k=JSON.parse('{"title":"2. 레일 & 스프링 너트","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/add-on/rail-spring-nut.md","filePath":"ko/guides/add-on/rail-spring-nut.md","lastUpdated":1785806767000}'),p={name:"ko/guides/add-on/rail-spring-nut.md"};function m(h,t,u,f,_,y){return g(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="_2-레일-스프링-너트" tabindex="-1">2. 레일 &amp; 스프링 너트 <a class="header-anchor" href="#_2-레일-스프링-너트" aria-label="Permalink to &quot;2. 레일 &amp; 스프링 너트&quot;">​</a></h1><p><strong>목표:</strong> 스프링 너트를 사용해 추가 모듈 하드웨어를 로봇 상부 레일에 장착합니다.</p><p><strong>사전 조건:</strong> 1단계 <a href="/RBQ/ko/guides/add-on/specifications.html">사양 확인</a> 완료 — 추가 모듈이 적재량/인터페이스 한계 내에 있어야 합니다.</p><h2 id="필요한-것" tabindex="-1">필요한 것 <a class="header-anchor" href="#필요한-것" aria-label="Permalink to &quot;필요한 것&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>상세</th></tr></thead><tbody><tr><td><strong>스프링 너트</strong></td><td>MISUMI <strong>SHNTP5-5</strong> (<a href="https://kr.misumi-ec.com/vona2/detail/110302608410/?HissuCode=SHNTP5-5&amp;PNSearch=SHNTP5-5&amp;searchFlow=results2products&amp;list=PageSearchResult" target="_blank" rel="noreferrer">KR</a> · <a href="https://us.misumi-ec.com/vona2/detail/110302247640/?PNSearch=SHNTP5-5&amp;HissuCode=SHNTP5-5&amp;seriesCode=110302247640&amp;tab=drawingAndSpecifications&amp;Page=1" target="_blank" rel="noreferrer">US</a>)</td></tr><tr><td><strong>볼트</strong></td><td>추가 모듈 장착부에 맞는 M5 볼트</td></tr><tr><td><strong>강체 막대</strong></td><td>제거용, <strong>직경 ≤ 4 mm</strong></td></tr></tbody></table><p>로봇 상부 레일은 선택 하드웨어(PTZ 카메라, LiDAR, 커스텀 브래킷)를 장착하기 위한 인터페이스입니다. 레일 슬롯에 스프링 너트를 삽입하면 M5 볼트를 체결할 수 있는 나사 고정점이 생깁니다.</p><h2 id="스프링-너트-삽입" tabindex="-1">스프링 너트 삽입 <a class="header-anchor" href="#스프링-너트-삽입" aria-label="Permalink to &quot;스프링 너트 삽입&quot;">​</a></h2><ol><li><strong>비스듬히 삽입</strong> — 스프링 너트를 레일 슬롯에 <strong>대각선으로</strong> 밀어 넣어 내부 채널로 진입시킵니다.</li><li><strong>돌출부 누르기</strong> — 너트 일부가 슬롯 위로 돌출될 수 있으니, 채널에 완전히 안착할 때까지 눌러줍니다.</li><li><strong>레일과 정렬</strong> — 슬롯과 정렬되어 레일을 따라 자유롭게 이동할 수 있도록 조정합니다.</li></ol><figure style="text-align:center;"><img src="'+a+'" alt="1단계 - 비스듬히 삽입" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">1단계 — 비스듬히 삽입</figcaption></figure><figure style="text-align:center;"><img src="'+e+'" alt="2단계 - 돌출부 누르기" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">2단계 — 돌출부 누르기</figcaption></figure><figure style="text-align:center;"><img src="'+i+'" alt="3단계 - 슬롯과 정렬" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">3단계 — 슬롯과 정렬</figcaption></figure><p>너트를 추가 모듈 브래킷이 위치할 곳까지 이동시킨 후 M5 볼트로 브래킷을 고정합니다.</p><h2 id="스프링-너트-제거" tabindex="-1">스프링 너트 제거 <a class="header-anchor" href="#스프링-너트-제거" aria-label="Permalink to &quot;스프링 너트 제거&quot;">​</a></h2><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p><strong>공구 직경:</strong> 직경 <strong>4 mm 이하</strong>의 강체 막대를 사용하세요. 더 굵은 공구는 너트를 손상하거나 레일 슬롯에 흠집을 낼 수 있습니다.</p></div></div><ol><li><strong>막대 삽입</strong> — 스프링 너트의 구멍에 강체 막대(<strong>≤ 4 mm</strong>)를 통과시킵니다.</li><li><strong>한쪽 벽으로 밀기</strong> — 너트를 레일 슬롯의 한쪽 내벽 방향으로 밀어줍니다.</li><li><strong>비틀어 들어올리기</strong> — 한쪽 벽에 댄 상태로 반대편으로 비틀어 들어올려 너트가 레일 단면을 벗어나게 합니다.</li><li><strong>제거</strong> — 슬롯에서 너트를 빼냅니다.</li></ol><figure style="text-align:center;"><img src="'+r+'" alt="1단계 - 막대를 구멍에 통과" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">1단계 — 막대를 구멍에 통과</figcaption></figure><figure style="text-align:center;"><img src="'+s+'" alt="2단계 - 한쪽 벽으로 밀기" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">2단계 — 한쪽 벽으로 밀기</figcaption></figure><figure style="text-align:center;"><img src="'+o+'" alt="3단계 - 비틀어 들어올리기" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">3단계 — 비틀어 들어올리기</figcaption></figure><figure style="text-align:center;"><img src="'+n+'" alt="4단계 - 제거" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">4단계 — 제거</figcaption></figure><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>하드웨어 장착이 끝났습니다. 이제 GUI에서 추가 모듈의 질량과 오프셋을 등록합니다:</p><p><strong><a href="/RBQ/ko/guides/add-on/payload-setting.html">→ 3. Payload 설정</a></strong></p>',22)])])}const P=l(p,[["render",m]]);export{k as __pageData,P as default};
